      SUBROUTINE RINV1CC     CALCULATES INVERSE OF FIRST-ORDER TRANSFER MATRIXCC ----------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ELM10D.CIN'      INCLUDE 'RS.CIN'C      PMARQ = 0.0      DO 310 J = 1, 7      SCALE(J) = 1.0  310 CA(J,1) = 0.0      DO 320 J = 1, 6      DO 320 K = 1, 6      RT(J,K) = RS(J,K)  320 CA(J+1,K+1) = RS(J,K)      NSAVE = NV1      NV1 = 6      CALL INQ      NV1 = NSAVE      DO 330 J = 1, 6      DO 330 K = 1, 6  330 RS(J,K) = CA(J+1,K+1)      RETURN      END